// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport java.lang.reflect.Method/** * NOUS — Registry-Backed Accessibility Service (Module 10 v2 — audit defect C fix). * * Real implementation of [NousAccessibilityServiceInterface] that delegates * to Module 9's [com.roshan.persona.agent.accessibility.AccessibilityServiceRegistry] * (which holds the active [com.roshan.persona.agent.accessibility.NousAccessibilityService] * instance, registered by Android when the user enables it in Settings → * Accessibility). * * ## Why reflection? * * `:feature:system` cannot depend on `:feature:agent` (Module 9 depends on * Module 10, so a reverse dep would create a cycle). Reflection lets Module * 10 reach Module 9's static registry at runtime without a compile-time * dependency. This is a standard pattern for plugin architectures (e.g., * Firebase apps reach Google Play Services via reflection on lower API levels). * * ## Lifecycle * *  - When the user enables the NOUS Accessibility Service in Settings, *    Android instantiates `NousAccessibilityService`, which calls *    `AccessibilityServiceRegistry.register(this)` in `onServiceConnected()`. *  - [isServiceEnabled] / [performGlobalAction] then succeed. *  - When the user disables it, `onUnbind()` calls `unregister()` — these *    methods gracefully return `false`. * * ## Testability * * Tests that don't have Module 9 on the classpath will see * `ClassNotFoundException` from [Class.forName] — caught + logged at debug * level, and the methods return `false` (matching [NoopAccessibilityService] * semantics). This keeps `:feature:system:compileDevDebugKotlin` standalone * (no need to depend on `:feature:agent` at compile time). * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Privacy & Security — Screen Lock</a> */class RegistryBackedAccessibilityService : NousAccessibilityServiceInterface {    /**     * Reflective lookup of Module 9's `AccessibilityServiceRegistry.getInstance()`.     *     * Returns the active `NousAccessibilityService` instance, or null if:     *  - Module 9 isn't on the classpath (e.g., `:feature:system` tests).     *  - The user hasn't enabled the accessibility service yet.     */    private fun lookupService(): Any? = try {        val cls = Class.forName(REGISTRY_CLASS_NAME)        // Kotlin `object` compiles to a class with a static INSTANCE field.        val getInstanceMethod = cls.getMethod("getInstance")        getInstanceMethod.invoke(null)    } catch (e: ClassNotFoundException) {        // Module 9 not on classpath — expected in :feature:system standalone.        null    } catch (e: NoSuchMethodException) {        Timber.tag(TAG).w("AccessibilityServiceRegistry.getInstance not found", e)        null    } catch (t: Throwable) {        Timber.tag(TAG).w(t, "Failed to look up NousAccessibilityService")        null    }    override fun isServiceEnabled(): Boolean = lookupService() != null    override fun performGlobalAction(action: Int): Boolean {        val service = lookupService() ?: return false        return try {            // NousAccessibilityService exposes executeGlobalAction(action: Int): Boolean.            val method: Method = service.javaClass.getMethod(                "executeGlobalAction",                Int::class.javaPrimitiveType,            )            (method.invoke(service, action) as? Boolean) ?: false        } catch (e: NoSuchMethodException) {            Timber.tag(TAG).w(e, "executeGlobalAction method not found on service")            false        } catch (t: Throwable) {            Timber.tag(TAG).w(t, "performGlobalAction failed for action=$action")            false        }    }    private companion object {        private const val TAG = "RegistryA11y"        private const val REGISTRY_CLASS_NAME =            "com.roshan.persona.agent.accessibility.AccessibilityServiceRegistry"    }}